from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0576-B{k:04d}']=t
p(2,'“大 Waaagh!”是碎骨者·斯拉卡发动、在本篇所述时期仍持续的欧克战争浪潮。自“野兽”以来，八千年间，从未出现过如此庞大的 Waaagh!。')
p(4,'Ghazghkull during the "Da Great Waaagh" “大 Waaagh!”期间的碎骨者·斯拉卡')
p(7,'990998.M41，阿玛吉多顿入侵久拖不决，碎骨者的异象愈发频繁，伴随剧痛与闪烁绿光，搞哥、毛哥不满的怒吼在脑中回荡。他将战事交给诸将，回到指挥舰杀戮破坏者号独自思索，又召来一群次元脑袋，希望这些疯癫的灵能者解读异象。但最终想通的是他自己：其他欧克都没有这样的雄心，一场阿玛吉多顿式的痛快大战，便足以令他们满足；他却看见了更宏大的目标。突如其来的狂热驱使他下令离开轨道，召集附近能找到的欧克战舰，拼成一支杂乱舰队，驶向星系边缘。他不知道自己在找什么，只知道答案不在阿玛吉多顿。')
p(9,'碎骨者的离去并未逃过监视。深空探测站发现杀戮破坏者号驶出星系，随即通知最高指挥部。雅瑞克政委与黑色圣堂至高元帅赫尔布雷彻决定追击，数日后率领所有能够抽调的战舰启程。帝国曾让碎骨者逃走一次，并为此付出惨重代价；雅瑞克发誓，同样的错误绝不会重演。')
p(12,'碎骨者虽抢先出发，追兵却始终准确掌握其行踪。离开阿玛吉多顿数周后，航速与效率更高的帝国海军追上欧克舰队。在“闹鬼湾”这片死寂空域，欧克走投无路，掉头迎着帝国炮火发起最后冲锋。光矛与舷炮照亮虚空，欧克舰船猛冲敌阵，却几无胜算：虽然重创数艘帝国巡洋舰，自己仍被逐一撕碎。雅瑞克与赫尔布雷彻正准备跳帮杀戮破坏者号，彻底除掉碎骨者，目标却突然被炽烈绿能包裹，消失无踪。原处留下一片迅速扩大的空间异常，迫使追兵撤离。数日内，异常膨胀为亚空间风暴，再与其他风暴连成一体，成为大裂隙的一部分。')
p(14,'舰队遭撕碎时，碎骨者仍在舰桥大步来回，怒吼着下令。强烈异象令他怒火沸腾，绿色闪电环绕身体。突增的能量压垮随侍次元脑袋的心智，他们齐齐抽搐、嚎叫、胡言乱语。碎骨者头颅周围的绿光猛然抽向这些灵能者，将其吞入烈焰；眼球爆裂，皮肤焦灼，灵质力量从口中喷涌。他们齐声发出搞哥与毛哥的怒吼——正是碎骨者数月来听到的声音。神祇宣告，现在还不是他死的时候。听见神谕的欧克全都敬畏跪下。整个银河必须回荡欧克的战吼，而碎骨者受命集结前所未有的 Waaagh!，属于搞哥与毛哥自己的 Waaagh!。他须击败所有军阀，收服每一个绿皮，率全族远征，将群星淹没于战争。唯有完成这场“大 Waaagh!”，才能召来两位神，带领小子们投入永无终结的辉煌大战。神谕传毕，灵能小子们爆成一场血肉之雨，绿色能量向外席卷，烧毁杀戮破坏者号的全部系统，也使追兵受创瘫痪。巨舰随即被抛入亚空间，在全然不同的地点——甚至时间——重新出现。')
p(17,'694999.M41，杀戮破坏者号跃出亚空间，来到军阀“杀戮者”乌尔戈克的广阔领地。碎骨者精神大振，赤红双眼燃起新的目标，径直驶向对方的太空堡垒。他明白自己唯一的优势就是突然袭击，便启动传送器，带着最凶悍的一群强蛮人，在轰鸣光爆中直接闯入乌尔戈克的王座室。守卫被他轻易撕碎，如同一群吵闹的屁精。乌尔戈克惊恐地看着他踩过尸体逼近；大枪仍冒着烟，这位庞大军阀俯视着已被吓破胆的对手，“邀请”其加入大 Waaagh!。')
p(19,'乌尔戈克麾下大多数小子欣然加入，反应迟钝、看不清风向的，则很快被打到服从。数周内，碎骨者发起新 Waaagh!的消息传遍四方，连数百光年外的欧克也听到传说，一场空前规模的迁徙开始萌动。掌握新联军、收下乌尔戈克这个跟班后，碎骨者转而关注银河东南方的奥克塔琉斯帝国。若要让战争吞没银河，搞哥与毛哥还需要更多欧克。况且，他也想让当地统治者见识一下，真正的“暴君”该是什么模样……')
p(21,'奥克塔琉斯已由欧克统治数千标准年。它不像乌尔克所在的星区分区那般偏僻，经常有头目崛起，召集 Waaagh!，向银河某处大举劫掠。老军阀戈尔斯尼克·马加什便曾赶赴各各他星区，追随碎骨者；此时正率大军在阿玛吉多顿死地坚守。自他离开，死颅军阀佐格·钢牙迅速填补权力真空，自封奥克塔琉斯暴君。但帝国正与泰伦大战，他的统治并不稳固。碎骨者见到如此痛快的战机，立刻率军迎击虫群。斩杀一头强大的沙蟒之后，他成为奥克塔琉斯战区欧克军队事实上的领袖，并认为这里比阿玛吉多顿还大有可为。')
p(23,'此后，碎骨者离开奥克塔琉斯战区。据本篇记载，他正率领一支五百万艘舰船组成的舰队，进攻帝国。')
p(26,'灵能觉醒期间，碎骨者与盟军对上太空野狼，战事在克朗加达到高潮。他与拉格纳·黑鬃决斗，后者虽重伤，仍将其斩首。戈斯尼克紧急手术救回了碎骨者，使他比以往更强大。')
p(28,'碎骨者接受手术时，野心勃勃的特种兵“死亡上校”佐格头目，试图夺取大 Waaagh!的领导权。他率众攻入戈斯尼克的实验室，却只有自己冲进最内层，随即摧毁设备，准备杀死疯医。然而，他来迟一步：尚未出手，复苏的碎骨者就一把攥住他的脑袋，轻易捏碎。')
p(31,'大 Waaagh!的影响遍及银河。欧克大量聚集于奥克塔瑞亚，激起疯小子的浩瀚灵能浪潮。帝国中，每一个对亚空间敏感的灵魂都感到它在非物质界回荡；明白其含义者，无不恐惧。这股浪潮又如灵能灯塔，将银河各地的欧克引向碎骨者麾下。')
p(33,'情报部提交的报告，对碎骨者的位置说法互相冲突，令帝国高层不安。他似乎既在奥克塔琉斯，又同时洗劫坎蒂萨、现身奥罗克塔杀戮场、出没于帝国暗面，并在瑞扎附近作战。有推测称，欧克正借亚空间风暴穿行银河；极端的亚空间时间膨胀，也可能造成这些矛盾。')
n.update({'A0576-B0007':'990998.M41为底稿原有异常纪年格式，保留原样待原始出版物核实，不擅改成年份或补日期；Kill Wrecka统一杀戮破坏者号，非杀死破坏者。','A0576-B0009':'auger-stations为探测站，不是螺旋空间站；can be spared为可抽调，不是战斗中幸免。High Marshal Helbrecht沿官方至高元帅赫尔布雷彻。Yarrick采用GW09第8页中文雅瑞克，英文旧版未列而标参考。','A0576-B0012':'turn at bay为被逼入绝境后的反击，不是地理海湾转弯；cripple为重创，不必然摧毁。','A0576-B0014':'bridge为舰桥；charge with为赋予使命；some-when刻意强调时间也改变，保留叙事重点。','A0576-B0017':'694999.M41同样保留底稿异常格式；baddest为最凶悍，loom over为高大身形压迫，不是隐约出现。Nobz统一强蛮人。','A0576-B0021':'Urk为乌尔克地名，原译误作前段人物乌尔戈克；subsector为星区分区，backwater为偏远落后。Overfiend为欧克统治者称号暴君，不是真正的超级恶魔。','A0576-B0023':'五百万艘为所给英文的具体数量，保持原值并注明资料时点。','A0576-B0028':'Kommando为欧克特种兵身份，不是一般指挥官；Deff-Kolonel为带欧克口音的死亡上校称号。','A0576-B0033':'原句列举数个同时现身地点，原译把坎蒂萨、奥罗克塔与帝国暗面合成一个地点，已恢复并列关系。'})
rows=list(csv.DictReader((P/'terms.tsv').open(),delimiter='\t'));cols=list(rows[0]);by={r[cols[0]].casefold():r for r in rows}
for en,zh in [('Da Great Waaagh!','大 Waaagh!'),('Kill Wrecka','杀戮破坏者号'),('Warpheads','次元脑袋'),('Haunted Gulf','闹鬼湾'),('Octaria','奥克塔瑞亚'),('Urgok Da Slayer','杀戮者乌尔戈克'),('Urk','乌尔克'),('Gorsnik Magash','戈尔斯尼克·马加什'),('Golgotha Sector','各各他星区'),('Dead Lands','死地'),('Zog Steeltoof','佐格·钢牙'),('Krongar','克朗加'),('Deff-Kolonel Zogboss','死亡上校佐格头目'),('Madboyz','疯小子'),('Cantissa','坎蒂萨'),('Aurochtha','奥罗克塔')]:by.setdefault(en.casefold(),dict(zip(cols,[en,zh,'暂定·官方待核','所给英文底稿','篇0576','依原稿语境区分人物、地点、欧克头衔，来源纪年疑点见校注。'])))
u9='https://assets.warhammer-community.com/chi_06-05_wh40k_core%26key_munitorum_field_manual-5mrlucr2t1-fkybzzzoce.pdf';u10='https://assets.warhammer-community.com/eng_warhammer40000_munitorum_field_manual_march_2025-cims9ya3sg-s8j9m2haae.pdf'
by['mawloc']=dict(zip(cols,['Mawloc','沙蟒','官方已核对',f'GW-09 {u9}；GW-10 {u10}','GW09第37页；GW10第36页','官方中英单位逐项核对。']))
by['commissar yarrick']=dict(zip(cols,['Commissar Yarrick','雅瑞克政委','官方中文参考·英文对应待复核',f'GW-09 {u9}','中文PDF第8页；英文名见底稿576','GW10旧版同栏未列，不冒充双版对应核对。']))
with (P/'terms.tsv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=cols,delimiter='\t');w.writeheader();w.writerows(by.values())
for fn,obj in [('edits.json',e),('notes.json',n)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
rv=set(json.loads((P/'reviewed.json').read_text()))|{576};(P/'reviewed.json').write_text(json.dumps(sorted(rv)))
print('576 complete')
